const KEY='registro-arcano-v1';
const names=['Forza','Destrezza','Costituzione','Intelligenza','Saggezza','Carisma'];
const skills=[['Acrobazia',1],['Addestrare Animali',4],['Arcano',3],['Atletica',0],['Furtività',1],['Indagare',3],['Inganno',5],['Intimidire',5],['Intuizione',4],['Intrattenere',5],['Medicina',4],['Natura',3],['Percezione',4],['Persuasione',5],['Rapidità di mano',1],['Religione',3],['Sopravvivenza',4],['Storia',3]];
const defaults=()=>({identity:{nome:'',classe:'',sottoclasse:'',razza:'',livello:'',background:'',xp:''},stats:{ca:'',velocita:'',competenza:'',iniziativa:''},hp:{attuali:0,massimi:0,temporanei:0},death:{successi:[false,false,false],fallimenti:[false,false,false]},abilities:names.map(()=>({score:'',save:0})),skills:skills.map(()=>0),slots:Array.from({length:9},()=>({max:0,current:0})),sorcery:{current:0,max:0},coins:{MR:0,MA:0,MO:0,MP:0},spells:[],items:[],notes:{tratti:'',privilegi:'',talenti:'',capacita:'',metamagie:'',equipaggiamento:'',condizioni:'',personali:''},inspiration:false,catalog:[]});
let state;try{state=JSON.parse(localStorage.getItem(KEY))||defaults()}catch{state=defaults()}let page='overview', filter='',search='';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){localStorage.setItem(KEY,JSON.stringify(state))}function get(path){return path.split('.').reduce((a,k)=>a[k],state)}function set(path,v){let p=path.split('.'),last=p.pop(),o=p.reduce((a,k)=>a[k],state);o[last]=v;save()}
function field(label,path,type='text',extra=''){return `<div class="field ${extra}"><label>${label}</label><input type="${type}" data-path="${path}" value="${esc(get(path))}" ${type==='number'?'min="0" step="1"':''} placeholder="—"></div>`}
function counter(label,path){return `<div class="resource-row"><b>${label}</b><div class="controls"><button data-step="${path}" data-delta="-1" aria-label="Riduci ${label}">−</button><input type="number" min="0" step="1" data-path="${path}" value="${esc(get(path))}" aria-label="${label}"><button data-step="${path}" data-delta="1" aria-label="Aumenta ${label}">+</button></div></div>`}
function title(t,sub,action=''){return `<div class="page-head"><div><div class="eyebrow">✦ &nbsp; IL TUO REGISTRO PERSONALE</div><h1>${t}</h1><p>${sub}</p></div>${action||'<div class="ornament">✧ &nbsp; ─── &nbsp; ✧</div>'}</div>`}function card(t,body,cls='',meta=''){return `<section class="card ${cls}"><div class="card-title"><h2><span>✧</span>${t}</h2><small>${meta}</small></div>${body}</section>`}function mod(n){return n===''?'—':fmt(Math.floor((Number(n)-10)/2))}function fmt(n){return n>=0?'+'+n:String(n)}function pct(a,b){return b>0?Math.max(0,Math.min(100,a/b*100)):0}
function overview(){let h=state.hp;return title('La tua avventura','Tutto ciò che conta, a portata di mano.')+`<div class="grid">`+card('IDENTITÀ DEL PERSONAGGIO',`<div class="identity">${field('Nome','identity.nome')}${field('Classe','identity.classe')}${field('Sottoclasse','identity.sottoclasse')}${field('Razza','identity.razza')}${field('Livello','identity.livello','number')}${field('Background','identity.background')}${field('Punti esperienza','identity.xp','number')}</div>`,'','LA TUA STORIA')+card('DIFESE E MOVIMENTO',`<div class="stats">${[['Classe armatura','ca'],['Velocità','velocita'],['Bonus competenza','competenza'],['Iniziativa','iniziativa']].map(([l,k])=>`<div class="stat"><span class="tiny">${l}</span><input type="number" data-path="stats.${k}" value="${esc(state.stats[k])}" aria-label="${l}" placeholder="—"></div>`).join('')}</div>`,'','PRONTO ALL’AZIONE')+card('PUNTI VITA',`<div class="health-main"><div class="health-number">${h.attuali} <span>/ ${h.massimi}</span></div><div class="health-detail"><div class="bar-caption"><span>VITALITÀ</span><span>${Math.round(pct(h.attuali,h.massimi))}%</span></div><div class="bar"><div class="fill" style="width:${pct(h.attuali,h.massimi)}%"></div></div><div class="sub">${h.temporanei} punti vita temporanei</div></div></div><div class="hp-actions"><input id="hpAmount" type="number" min="0" value="1" aria-label="Quantità punti vita"><button class="secondary" data-hp="damage">− Subisci danni</button><button class="primary" data-hp="heal">+ Recupera</button></div>${counter('Punti vita attuali','hp.attuali')}${counter('Punti vita massimi','hp.massimi')}${counter('Punti vita temporanei','hp.temporanei')}`,'half','STATO VITALE')+card('TIRI SALVEZZA CONTRO MORTE',`<p class="sub">Segna successi e fallimenti quando il destino è in bilico.</p><div class="death" style="margin-top:22px">${['successi','fallimenti'].map(k=>`<div class="checks">${k.toUpperCase()} ${state.death[k].map((v,i)=>`<input type="checkbox" data-path="death.${k}.${i}" ${v?'checked':''} aria-label="${k} ${i+1}">`).join('')}</div>`).join('')}</div><div class="resource-row" style="margin-top:23px"><b>Ispirazione</b><input type="checkbox" data-path="inspiration" ${state.inspiration?'checked':''}></div>`,'half','IL FILO DEL DESTINO')+card('CARATTERISTICHE',abilityCards(),'','I TUOI ATTRIBUTI')+`</div>`}
function abilityCards(){return `<div class="ability-grid">${names.map((n,i)=>`<div class="ability"><strong>${n.toUpperCase()}</strong><div class="mod">${mod(state.abilities[i].score)}</div><input type="number" min="1" max="30" data-path="abilities.${i}.score" value="${esc(state.abilities[i].score)}" aria-label="Punteggio ${n}" placeholder="—"><small>PUNTEGGIO</small></div>`).join('')}</div>`}
function abilities(){return title('Caratteristiche','I tuoi attributi, tiri salvezza e competenze.')+`<div class="grid">`+card('CARATTERISTICHE',abilityCards(),'','PUNTEGGI E MODIFICATORI')+card('TIRI SALVEZZA',`<p class="sub">Indica la competenza: il bonus usa il modificatore e il bonus di competenza.</p>${names.map((n,i)=>`<div class="resource-row"><b>${n} &nbsp; <span class="tag">${state.abilities[i].score===''?'—':fmt(Math.floor((Number(state.abilities[i].score)-10)/2)+(Number(state.stats.competenza)||0)*Number(state.abilities[i].save))}</span></b><label class="checks"><input type="checkbox" data-path="abilities.${i}.save" ${state.abilities[i].save?'checked':''}> Competente</label></div>`).join('')}`,'half')+card('ABILITÀ',`<div class="skill-grid">${skills.map(([n,a],i)=>`<div class="skill"><span>${n}</span><span class="tiny">${names[a].slice(0,3)}</span><span class="bonus">${state.abilities[a].score===''?'—':fmt(Math.floor((Number(state.abilities[a].score)-10)/2)+(Number(state.stats.competenza)||0)*Number(state.skills[i]))}</span><select data-path="skills.${i}" aria-label="Competenza ${n}"><option value="0" ${state.skills[i]==0?'selected':''}>—</option><option value="1" ${state.skills[i]==1?'selected':''}>Comp.</option><option value="2" ${state.skills[i]==2?'selected':''}>Exp.</option></select></div>`).join('')}</div>`,'half')+`</div>`}
function magic(){let s=state.sorcery;return title('Incantesimi','La magia a tua disposizione, pronta quando serve.',`<button class="primary" data-add="spells">+ Aggiungi incantesimo</button>`)+`<div class="grid">`+card('SLOT INCANTESIMO',`<p class="sub">Imposta manualmente gli slot previsti dal personaggio. I livelli senza slot restano disponibili per la configurazione.</p>${state.slots.map((x,i)=>`<div class="resource-row"><b>Livello ${i+1}</b><div class="slot">${Array.from({length:Math.min(x.max,20)},(_,j)=>`<span class="orb ${j>=x.current?'used':''}"></span>`).join('')} <span class="tiny">${x.current} / ${x.max}</span><div class="controls"><button data-slot="${i}" data-delta="-1">−</button><button data-slot="${i}" data-delta="1">+</button></div><label class="tiny">MAX <input type="number" min="0" data-slot-max="${i}" value="${x.max}" style="width:48px;background:#18201e;color:white;border:1px solid #414943;padding:6px"></label></div></div>`).join('')}`,'half','LIVELLI 1–9')+card('PUNTI STREGONERIA',`<div class="health-number">${s.current} <span>/ ${s.max}</span></div><div class="bar"><div class="fill gold" style="width:${pct(s.current,s.max)}%"></div></div>${counter('Punti attuali','sorcery.current')}${counter('Punti massimi','sorcery.max')}<div style="margin-top:20px"><div class="tiny">CONVERSIONE MAGICA · STREGONE 5E 2014</div><p class="sub">Creare uno slot consuma punti (livelli 1–5: 2, 3, 5, 6, 7). Convertire uno slot restituisce punti pari al suo livello, fino al massimo.</p><div class="row"><select id="convertLevel" style="width:140px">${[1,2,3,4,5,6,7,8,9].map(i=>`<option value="${i}">Livello ${i}</option>`).join('')}</select><button class="secondary" data-convert="create">Crea slot</button><button class="secondary" data-convert="points">Ottieni punti</button></div><p class="sub">Gli slot creati possono superare il massimo configurato; scompaiono al termine di un riposo lungo.</p></div>`,'half','FONTE DI MAGIA')+card('LIBRO DEGLI INCANTESIMI',`<div class="toolbar"><input class="search" id="spellSearch" placeholder="Cerca un incantesimo…" value="${esc(search)}"><select id="spellFilter"><option value="">Tutti i livelli</option>${Array.from({length:10},(_,i)=>`<option value="${i}" ${filter===String(i)?'selected':''}>${i===0?'Trucchetto':'Livello '+i}</option>`).join('')}</select></div><div id="spellList">${spellList()}</div>`)+card('METAMAGIE',`${(state.catalog||[]).filter(x=>x.type==='metamagic').map(x=>`<div class="list-item"><div><strong>${esc(x.name)}</strong><p>${esc(x.description)}</p></div></div>`).join('')}<div class="field"><label>Metamagie conosciute ed effetti</label><textarea rows="5" data-path="notes.metamagie" placeholder="Annota qui le tue metamagie…">${esc(state.notes.metamagie)}</textarea></div>`)+`</div>`}
function spellList(){let a=state.spells.map((x,i)=>({...x,i})).filter(x=>(filter===''||String(x.livello)===filter)&&x.nome.toLowerCase().includes(search.toLowerCase()));return a.length?a.map(x=>`<div class="list-item"><div><strong>${esc(x.nome)}</strong> <span class="tag">${x.livello==='0'?'TRUCCHETTO':'LIVELLO '+esc(x.livello)}</span><p>${esc([x.scuola,x.lancio,x.gittata,x.durata,x.componenti].filter(Boolean).join(' · '))}</p><p>${esc(x.descrizione)} ${esc(x.effetti)}</p></div><div class="row"><button class="secondary" data-edit="spells:${x.i}">Modifica</button><button class="secondary" data-delete="spells:${x.i}">Elimina</button></div></div>`).join(''):'<div class="empty"><b>Il tuo grimorio è ancora vuoto</b>Aggiungi un incantesimo o modifica i filtri di ricerca.</div>'}
function inventory(){let c=state.coins,total=(+c.MR/100)+(+c.MA/10)+(+c.MO)+(+c.MP*10);return title('Inventario','Ogni oggetto ha una storia da raccontare.',`<button class="primary" data-add="items">+ Aggiungi oggetto</button>`)+`<div class="grid">`+card('BORSA DELL’AVVENTURIERO',state.items.length?state.items.map((x,i)=>`<div class="list-item"><div><strong>${esc(x.nome)}</strong> <span class="tag">${esc(x.tipo)}</span> ${x.equipaggiato?'<span class="tag">EQUIPAGGIATO</span>':''}<p>Quantità ${esc(x.quantita)} · ${esc(x.peso||'0')} kg ciascuno · ${esc(x.valore||'0')} MO</p><p>${esc(x.descrizione)}</p></div><div class="row"><button class="secondary" data-edit="items:${i}">Modifica</button><button class="secondary" data-delete="items:${i}">Elimina</button></div></div>`).join(''):'<div class="empty"><b>La tua borsa è vuota</b>Aggiungi armi, pozioni e tesori raccolti durante le tue avventure.</div>','two-third',`PESO TOTALE ${state.items.reduce((a,x)=>a+(+x.quantita||0)*(+x.peso||0),0).toFixed(2)} KG`)+card('BORSA DELLE MONETE',Object.keys(c).map(k=>counter(({MR:'Rame · MR',MA:'Argento · MA',MO:'Oro · MO',MP:'Platino · MP'})[k],`coins.${k}`)).join('')+`<div class="resource-row"><b>Valore complessivo</b><strong style="color:var(--gold)">${total.toFixed(2)} MO</strong></div>`,'third','TESORO')+`</div>`}
function notes(){let labels={tratti:'Tratti razziali',privilegi:'Privilegi di classe',talenti:'Talenti',capacita:'Capacità speciali',metamagie:'Metamagie ed effetti',equipaggiamento:'Equipaggiamento attivo',condizioni:'Condizioni e stati alterati',personali:'Note personali'};return title('Tratti e note','Le capacità, i dettagli e i ricordi che rendono unico il tuo personaggio.')+`<div class="grid">${(state.catalog||[]).some(x=>!['metamagic'].includes(x.type))?card('OPZIONI DAL CATALOGO SRD',(state.catalog||[]).filter(x=>x.type!=='metamagic').map(x=>`<div class="list-item"><div><strong>${esc(x.name)}</strong> <span class="tag">${esc(x.kind)}</span><p>${esc(x.description)}</p></div></div>`).join('')):''}${Object.entries(labels).map(([k,v])=>card(v.toUpperCase(),`<div class="field"><textarea rows="5" data-path="notes.${k}" placeholder="Scrivi qui…">${esc(state.notes[k])}</textarea></div>`,'half')).join('')}</div>`}
function render(){document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#crumb').textContent=({overview:'PANORAMICA',abilities:'CARATTERISTICHE',magic:'INCANTESIMI',inventory:'INVENTARIO',notes:'TRATTI E NOTE',catalog:'CATALOGO SRD'})[page];$('#content').innerHTML=({overview,abilities,magic,inventory,notes,catalog})[page]()}
const spellFields=[['nome','Nome','text'],['livello','Livello','number'],['scuola','Scuola di magia','text'],['lancio','Tempo di lancio','text'],['gittata','Gittata','text'],['durata','Durata','text'],['componenti','Componenti','text'],['descrizione','Descrizione','textarea'],['effetti','Danni o effetti','textarea']];const itemFields=[['nome','Nome','text'],['quantita','Quantità','number'],['tipo','Tipologia','select'],['peso','Peso unitario (kg)','number'],['valore','Valore unitario (MO)','number'],['descrizione','Descrizione','textarea'],['equipaggiato','Equipaggiato','checkbox']];let editing;
function openEditor(type,index=null){editing={type,index};let item=index===null?{}:state[type][index],fields=type==='spells'?spellFields:itemFields;$('#dialogTitle').textContent=(index===null?'Aggiungi ':'Modifica ')+(type==='spells'?'incantesimo':'oggetto');$('#formFields').innerHTML=fields.map(([k,l,t])=>`<div class="field ${t==='textarea'?'wide':''}"><label for="f-${k}">${l}</label>${t==='textarea'?`<textarea id="f-${k}" name="${k}" rows="3">${esc(item[k]||'')}</textarea>`:t==='select'?`<select id="f-${k}" name="${k}">${['Armi','Armature','Oggetti magici','Pozioni','Equipaggiamento','Oggetti vari'].map(v=>`<option ${item[k]===v?'selected':''}>${v}</option>`).join('')}</select>`:t==='checkbox'?`<input id="f-${k}" name="${k}" type="checkbox" ${item[k]?'checked':''} style="width:auto;align-self:flex-start">`:`<input id="f-${k}" name="${k}" type="${t}" ${k==='nome'?'required':''} ${t==='number'?`min="0" step="${k==='peso'||k==='valore'?'0.01':'1'}"`:''} ${k==='livello'?'max="9" required':''} value="${esc(item[k]??(k==='quantita'?1:''))}">`}</div>`).join('');$('#editor').showModal()}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.page){page=b.dataset.page;render();window.scrollTo(0,0)}if(b.dataset.step){let p=b.dataset.step,v=Math.max(0,(Number(get(p))||0)+Number(b.dataset.delta));if(p==='hp.attuali')v=Math.min(v,state.hp.massimi);if(p==='sorcery.current')v=Math.min(v,state.sorcery.max);set(p,v);render()}if(b.dataset.hp){let n=Math.max(0,Number($('#hpAmount').value)||0);if(b.dataset.hp==='damage'){let absorbed=Math.min(state.hp.temporanei,n);state.hp.temporanei-=absorbed;state.hp.attuali=Math.max(0,state.hp.attuali-(n-absorbed))}else state.hp.attuali=Math.min(state.hp.massimi,state.hp.attuali+n);save();render()}if(b.dataset.slot!==undefined){let x=state.slots[+b.dataset.slot];x.current=Math.max(0,Math.min(x.max,x.current+Number(b.dataset.delta)));save();render()}if(b.dataset.convert){let l=Number($('#convertLevel').value),x=state.slots[l-1],cost=[0,2,3,5,6,7][l];if(b.dataset.convert==='create'){if(l>5)return alert('Puoi creare soltanto slot dal 1° al 5° livello.');if(state.sorcery.current<cost)return alert('Punti stregoneria insufficienti.');state.sorcery.current-=cost;x.max++;x.current++}else{if(!x.current)return alert('Nessuno slot disponibile a questo livello.');if(state.sorcery.current+l>state.sorcery.max)return alert('La conversione supererebbe il massimo dei punti stregoneria.');x.current--;state.sorcery.current+=l}save();render()}if(b.dataset.add)openEditor(b.dataset.add);if(b.dataset.edit){let [t,i]=b.dataset.edit.split(':');openEditor(t,+i)}if(b.dataset.delete){let [t,i]=b.dataset.delete.split(':');if(confirm('Eliminare questa voce?')){state[t].splice(+i,1);save();render()}}});
document.addEventListener('change',e=>{let el=e.target;if(el.dataset.path){let p=el.dataset.path,v=el.type==='checkbox'?(p.includes('.save')?Number(el.checked):el.checked):el.type==='number'?(el.value===''?'':Number(el.value)):el.tagName==='SELECT'?Number(el.value):el.value;if(el.type==='number'&&v!==''){if(el.min!=='')v=Math.max(Number(el.min),v);if(el.max!=='')v=Math.min(Number(el.max),v)}set(p,v);if(p==='hp.massimi')state.hp.attuali=Math.min(Number(state.hp.attuali)||0,Number(v)||0);if(p==='hp.attuali')state.hp.attuali=Math.min(Number(v)||0,Number(state.hp.massimi)||0);if(p==='sorcery.max')state.sorcery.current=Math.min(state.sorcery.current,Number(v)||0);if(p==='sorcery.current')state.sorcery.current=Math.min(Number(v)||0,state.sorcery.max);save();render()}if(el.dataset.slotMax!==undefined){let x=state.slots[+el.dataset.slotMax];x.max=Math.max(0,Math.floor(Number(el.value)||0));x.current=Math.min(x.current,x.max);save();render()}if(el.id==='spellFilter'){filter=el.value;$('#spellList').innerHTML=spellList()}});
document.addEventListener('input',e=>{let el=e.target;if(el.id==='spellSearch'){search=el.value;$('#spellList').innerHTML=spellList()}else if(el.dataset.path&&(el.tagName==='TEXTAREA'||el.type==='text'))set(el.dataset.path,el.value)});
$('#editorForm').addEventListener('submit',e=>{e.preventDefault();let fields=editing.type==='spells'?spellFields:itemFields,obj={};for(let [k,,t] of fields){let el=$('#f-'+k);obj[k]=t==='checkbox'?el.checked:el.value}if(editing.index===null)state[editing.type].push(obj);else state[editing.type][editing.index]=obj;save();$('#editor').close();render()});$('#closeDialog').onclick=$('#cancelDialog').onclick=()=>$('#editor').close();
$('#export').onclick=()=>{let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));a.download='registro-arcano.json';a.click();URL.revokeObjectURL(a.href)};
$('#import').onchange=async e=>{try{let data=JSON.parse(await e.target.files[0].text());if(!data.identity||!Array.isArray(data.abilities)||data.abilities.length!==6||!Array.isArray(data.slots)||data.slots.length!==9||!Array.isArray(data.spells)||!Array.isArray(data.items)||!data.hp||!data.notes||!data.coins||!data.sorcery||!data.death||!Array.isArray(data.skills)||!data.stats)throw Error();if(confirm('Sostituire la scheda attuale con il salvataggio importato?')){state=data;save();render()}}catch{alert('Il file non è una scheda Registro Arcano valida.')}e.target.value=''};
$('#reset').onclick=()=>{if(confirm('Ripristinare la scheda vuota? Tutti i dati attuali saranno cancellati. Esporta prima un backup se desideri conservarli.')){state=defaults();save();render()}};
window.addEventListener('beforeprint',()=>{document.body.dataset.oldpage=page;$('#content').innerHTML=[overview(),abilities(),magic(),inventory(),notes()].join('')});window.addEventListener('afterprint',render);render();
